public class ExpressionVisitorsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object value(Expr e) {
        try {
            return ExpressionVisitors.evaluate(e);
        } catch (RuntimeException ex) {
            return "threw " + ex.getClass().getSimpleName();
        }
    }

    static Object text(Expr e) {
        try {
            return ExpressionVisitors.print(e);
        } catch (RuntimeException ex) {
            return "threw " + ex.getClass().getSimpleName();
        }
    }

    static Object deep(Expr e) {
        try {
            return ExpressionVisitors.depth(e);
        } catch (RuntimeException ex) {
            return "threw " + ex.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        Expr leaf = new Num(7);
        Expr simple = new Add(new Num(1), new Mul(new Num(2), new Num(3)));
        Expr negated = new Neg(new Add(new Num(1), new Num(2)));
        Expr tall = new Mul(new Neg(new Neg(new Num(4))), new Add(new Num(5), new Num(6)));

        check("evaluate leaf", 7, value(leaf));
        check("evaluate 1 + 2 * 3", 7, value(simple));
        check("evaluate -(1 + 2)", -3, value(negated));
        check("evaluate a taller tree", 44, value(tall));
        check("evaluate a negative literal", -9, value(new Num(-9)));

        check("print leaf", "7", text(leaf));
        check("print 1 + 2 * 3", "(1 + (2 * 3))", text(simple));
        check("print -(1 + 2)", "-(1 + 2)", text(negated));
        check("print double negation", "(--4 * (5 + 6))", text(tall));

        check("depth of a leaf", 1, deep(leaf));
        check("depth of 1 + 2 * 3", 3, deep(simple));
        check("depth of the taller tree", 4, deep(tall));

        check("null evaluates to -1", -1, value(null));
        check("null prints as null", null, text(null));
        check("null depth is -1", -1, deep(null));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

