public class ExpressionVisitors {

    static class Evaluator implements ExprVisitor<Integer> {
        @Override
        public Integer visitNum(Num num) {
            return num.value();
        }

        @Override
        public Integer visitAdd(Add add) {
            return add.left().accept(this) + add.right().accept(this);
        }

        @Override
        public Integer visitMul(Mul mul) {
            return mul.left().accept(this) * mul.right().accept(this);
        }

        @Override
        public Integer visitNeg(Neg neg) {
            return -neg.operand().accept(this);
        }
    }

    static class Printer implements ExprVisitor<String> {
        @Override
        public String visitNum(Num num) {
            return String.valueOf(num.value());
        }

        @Override
        public String visitAdd(Add add) {
            return "(" + add.left().accept(this) + " + " + add.right().accept(this) + ")";
        }

        @Override
        public String visitMul(Mul mul) {
            return "(" + mul.left().accept(this) + " * " + mul.right().accept(this) + ")";
        }

        @Override
        public String visitNeg(Neg neg) {
            return "-" + neg.operand().accept(this);
        }
    }

    static class DepthMeasurer implements ExprVisitor<Integer> {
        @Override
        public Integer visitNum(Num num) {
            return 1;
        }

        @Override
        public Integer visitAdd(Add add) {
            return 1 + Math.max(add.left().accept(this), add.right().accept(this));
        }

        @Override
        public Integer visitMul(Mul mul) {
            return 1 + Math.max(mul.left().accept(this), mul.right().accept(this));
        }

        @Override
        public Integer visitNeg(Neg neg) {
            return 1 + neg.operand().accept(this);
        }
    }

    public static int evaluate(Expr expression) {
        if (expression == null) {
            return -1;
        }
        return expression.accept(new Evaluator());
    }

    public static String print(Expr expression) {
        if (expression == null) {
            return null;
        }
        return expression.accept(new Printer());
    }

    public static int depth(Expr expression) {
        if (expression == null) {
            return -1;
        }
        return expression.accept(new DepthMeasurer());
    }
}
